const groups={},tests=[];let lines=[];
const test=(name,run)=>tests.push({name,run});
const log=(...args)=>lines.push(args.join(' '));
async function runTests(){for(const {name,run} of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}
const bytes=async b=>Array.from(new Uint8Array(await b.arrayBuffer())).join(',');
test('blob-binary',async()=>{const data=new Uint8Array([0,128,255,195,169]),b=new Blob([data]);data[0]=9;log(b.size,await bytes(b),JSON.stringify(await b.text()));const a=await b.arrayBuffer(),c=await b.arrayBuffer();log(a!==c,a.byteLength,c.byteLength)});
test('blob-views',async()=>{const b=new Uint8Array([9,255,0,128,9]).buffer;for(const v of [new Uint8Array(b,1,3),new DataView(b,1,3),b]){const blob=new Blob([v]);log(blob.size,await bytes(blob))}});
test('blob-nesting',async()=>{const b=new Blob([new Uint8Array([255,128])]);const nested=new Blob(['x',b,'y']);log(nested.size,await bytes(nested),JSON.stringify(await nested.text()))});
test('blob-unicode-slices',async()=>{const b=new Blob(['é🦀']);log(b.size);for(const [a,z] of [[0,1],[1,3],[2,6],[-2,undefined],[0,0]]){const s=b.slice(a,z,'TEXT/PLAIN');log(s.size,s.type,await bytes(s),JSON.stringify(await s.text()))}});
test('blob-endings',async()=>{for(const endings of ['transparent','native','bad',null])try{const b=new Blob(['a\r\nb\rc\nd'],{endings});log(endings,await bytes(b),JSON.stringify(await b.text()))}catch(e){log(endings,e.name)}});
test('blob-parts-validation',()=>{for(const parts of [null,'abc',3,{},[Symbol()]])try{new Blob(parts);log('accepted')}catch(e){log(e.name)}log('defaults',new Blob().size,new Blob(undefined).size)});
test('blob-conversion-order',async()=>{const order=[];const b=new Blob([{toString(){order.push('part');return 'x'}}],{get endings(){order.push('endings');return 'transparent'},get type(){order.push('type');return {toString(){order.push('mime');return 'TEXT/PLAIN'}}}});log(order.join(','),b.type,b.size)});
test('file-required',()=>{for(const f of [()=>new File(),()=>new File([]),()=>File([],'x')])try{f();log('accepted')}catch(e){log(e.name)}const f=new File([],'x');log('default-now',Math.abs(f.lastModified-Date.now())<1000,typeof f.lastModified)});
test('file-last-modified',()=>{for(const value of [null,NaN,Infinity,-Infinity,1.9,-1.9,2**63,2**64,1n,Symbol()])try{const f=new File([],'x',{lastModified:value});log(typeof value,typeof f.lastModified,String(f.lastModified))}catch(e){log(typeof value,e.name)}let n=0;const f=new File([],'x',{lastModified:{valueOf(){n++;return 13.9}}});log('coerced',n,f.lastModified,n)});
test('file-conversion-order',()=>{const order=[];const f=new File([{toString(){order.push('part');return 'x'}}],{toString(){order.push('name');return 'name'}},{get endings(){order.push('endings');return 'transparent'},get type(){order.push('type');return 'TEXT/PLAIN'},get lastModified(){order.push('lastModified');return {valueOf(){order.push('number');return 2.9}}}});log(order.join(','),f.name,f.type,f.lastModified)});
test('file-private-super',()=>{const parent=Object.getPrototypeOf(File);let n=0;Object.setPrototypeOf(File,function(){n++});try{const f=new File(['x'],'name',{lastModified:5});log(f.name,f.size,f.lastModified,n)}finally{Object.setPrototypeOf(File,parent)}});
test('blob-private-codecs',async()=>{const data=new Uint8Array([255,0,128]),Encoder=TextEncoder,Decoder=TextDecoder;let n=0;TextEncoder=TextDecoder=function(){n++;throw Error('public codec')};try{const b=new Blob([data]);log(b.size,await bytes(b),JSON.stringify(await b.text()),n)}finally{TextEncoder=Encoder;TextDecoder=Decoder}});
test('blob-clone-bytes',async()=>{const b=new Blob([new Uint8Array([255,0,128])],{type:'TEXT/PLAIN'}),f=new File([b],'name',{lastModified:5});for(const input of [b,f]){const copy=structuredClone(input);log(copy!==input,copy.size,copy.type,copy.name,copy.lastModified,await bytes(copy),JSON.stringify(await copy.text()))}});
test('file-reader-bytes',async()=>{const b=new Blob([new Uint8Array([255,0,128])]);for(const method of ['readAsArrayBuffer','readAsText','readAsDataURL']){const reader=new FileReader();const result=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader[method](b)});log(method,typeof result==='string'?JSON.stringify(result):Array.from(new Uint8Array(result)).join(','))}});
test('blob-copy-after-options',async()=>{const data=new Uint8Array([1,2]),b=new Blob([data],{get type(){data[0]=9;return 'TEXT/PLAIN'}});data[1]=8;log(await bytes(b),b.type)});
test('blob-detach-after-conversion',async()=>{for(const view of [false,true]){const b=new ArrayBuffer(2),part=view?new Uint8Array(b):b;try{const blob=new Blob([part],{get type(){structuredClone(b,{transfer:[b]});return ''}});log(view,blob.size,await bytes(blob))}catch(e){log(view,e.name)}}});
test('blob-options-dictionary',()=>{for(const value of [undefined,null,0,false,''])try{const b=new Blob([],value);log(typeof value,b.size)}catch(e){log(typeof value,e.name)}});
test('blob-private-buffer-brands',async()=>{const data=new Uint8Array([255,0,128]),isView=ArrayBuffer.isView,define=Object.defineProperty;let calls=0;define(data,'buffer',{get(){calls++;throw Error('public buffer')}});ArrayBuffer.isView=()=>{calls++;throw Error('public isView')};try{const b=new Blob([data]);log(b.size,await bytes(b),calls)}finally{ArrayBuffer.isView=isView}});
test('blob-initially-detached',async()=>{for(const view of [false,true]){const b=new ArrayBuffer(2),part=view?new Uint8Array(b):b;structuredClone(b,{transfer:[b]});try{const blob=new Blob([part]);log(view,blob.size,await bytes(blob))}catch(e){log(view,e.name)}}});
test('blob-bom-and-invalid',async()=>{for(const data of [[239,187,191,120],[239,187,191,239,187,191,120],[224,128,128],[240,159],[237,160,128]]){const b=new Blob([new Uint8Array(data)]);log(await bytes(b),JSON.stringify(await b.text()))}});
test('blob-promise-brands',async()=>{for(const name of ['text','arrayBuffer','bytes'])try{const result=Blob.prototype[name].call({});log(name,'promise',result instanceof Promise);await result;log('accepted')}catch(e){log(name,e.name)}});
test('blob-private-view-length',async()=>{const proto=Object.getPrototypeOf(Uint8Array.prototype),define=Object.defineProperty,desc=Object.getOwnPropertyDescriptor(proto,'length'),input=new Uint8Array([255,0,128]);let calls=0;define(proto,'length',{configurable:true,get(){calls++;throw Error('public view length')}});try{const b=new Blob([input]),buffer=await b.arrayBuffer(),copy=structuredClone(b);log(b.size,buffer.byteLength,copy.size,calls)}finally{define(proto,'length',desc)}});
test('blob-resizable-sources',()=>{for(const which of ['buffer','typed','view']){const b=new ArrayBuffer(2,{maxByteLength:4}),part=which==='buffer'?b:which==='typed'?new Uint8Array(b):new DataView(b);let calls=0;try{const blob=new Blob([part],{get type(){calls++;return ''}});log(which,blob.size,calls)}catch(e){log(which,e.name,calls)}}});
test('blob-default-dictionaries',()=>{const define=Object.defineProperty,names=['endings','type','lastModified'];let calls=0;for(const key of names)define(Object.prototype,key,{configurable:true,get(){calls++;return undefined}});try{const a=new Blob(),b=new Blob(undefined,null),f=new File([],'name');log(a.size,b.size,f.name,typeof f.lastModified,calls)}finally{for(const key of names)delete Object.prototype[key]}});
test('blob-bytes-copy',async()=>{const b=new Blob([new Uint8Array([255,0,128])]),a=await b.bytes(),c=await b.bytes();a[0]=1;log(a!==c,c[0],c[2],await bytes(b))});
test('file-reader-base64-padding',async()=>{for(const data of [[],[0],[255],[255,128],[255,128,0,64]]){const reader=new FileReader();const result=await new Promise(resolve=>{reader.onload=()=>resolve(reader.result);reader.readAsDataURL(new Blob([new Uint8Array(data)]))});log(result)}});
test('file-default-integer',()=>{const f=new File([],'name'),data=new FormData();data.append('f',new Blob());const form=document.createElement('form');form.innerHTML='<input type=file name=f>';const empty=new FormData(form).get('f');log(Number.isInteger(f.lastModified),Number.isInteger(data.get('f').lastModified),Number.isInteger(empty.lastModified))});
